  ['rename header', 'diff --git a/old.txt b/new.txt\nsimilarity index 100%\nrename from old.txt\nrename to new.txt\n', 'new.txt'],
  ['mode-only header', 'diff --git a/a.txt b/a.txt\nold mode 100644\nnew mode 100755\n', 'a.txt'],
