    ['hunk-partial-context',context.subarray(0,middle),context.subarray(middle),['--side-by-side=hunk']]
  ]){
    if(onlyLabel&&label!==onlyLabel)continue;
    results.streaming.push({run,...await stream(binary,label,prefix,suffix,args)});
  }
}
if(!onlyLabel){
for(const binary of ['before','after'])for(const args of [[],['--lazygit-compat']]){
  const result=await new Promise((resolve,reject)=>{
    const child=spawn(path.join(dir,binary),[...common,...args],{env,detached:true,stdio:['pipe','ignore','pipe']});
    child.on('error',reject);child.stdin.on('error',()=>{});child.stdin.write(mixedPrefix);
    setTimeout(()=>{process.kill(-child.pid,'SIGTERM');},30);
    child.on('close',(code,signal)=>resolve({binary,args,code,signal}));
  });
  assert.equal(result.signal,'SIGTERM');results.cancellation.push(result);
}
for(const binary of ['before','after'])for(const args of [[],['--lazygit-compat']]){
  const result=await new Promise((resolve,reject)=>{
    const child=spawn(path.join(dir,binary),[...common,...args],{env,stdio:['pipe','pipe','pipe']});
    let error='';child.stderr.on('data',b=>error+=b);
    child.on('error',reject);child.stdin.on('error',()=>{});
    child.stdout.once('data',()=>child.stdout.destroy());
    child.stdin.end(fs.readFileSync(manifest.fixtures.find(f=>f.name==='go-12000').path));
    child.on('close',(code,signal)=>resolve({binary,args,code,signal,stderr:error}));
  });
  results.closedOutput.push(result);
}
for(const native of [false,true]){
  const matching=results.closedOutput.filter(r=>Boolean(r.args.length)===native);
  assert.equal(matching[0].code,matching[1].code);
  assert.equal(matching[0].signal,matching[1].signal);
  assert.equal(matching[0].stderr,matching[1].stderr);
}
}
fs.writeFileSync(path.join(dir,'extra-probes.json'),JSON.stringify(results,null,2)+'\n');
console.log(path.join(dir,'extra-probes.json'));

